schemas.schema-01-systematic.prisma:
/// Channel Entity - Implements the requirement for a unified platform channel registry as described in the architecture documentation. This table manages the definition and configuration of each business channel (web, mobile, partner integration, etc.), ensuring systematic onboarding, channel identity, routing controls, and auditability. Strict 3NF normalization—channel-specific settings and runtime data are separated into auxiliary tables to avoid redundancy. For example, creating an entry for a new branded web UI or a mobile app channel. Key relationships: sections, tenants, and API gateways reference this for channel-scoped logic. Special behaviors: Channels may be dynamically enabled/disabled, must be unique by code.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_channels {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Associated tenant's {@link ai_mall_backend_tenants.id}. Ensures that each channel is scoped to a valid tenant/brand context, enforcing strict multi-tenancy.
  tenant_id String @db.Uuid

  /// Channel code (slug or short name) - Implements the unique identity requirement. Used for routing and lookup, e.g., "web", "mobile", "partner1". Enforces normalization by not storing display names or configs redundantly.
  code String

  /// Human-readable channel name - For admin/business reference. For example, "Mobile App Channel (2025)", ensures normalized separation from settings or localized values.
  name String

  /// Activation flag - Implements the requirement for dynamic channel enable/disable. Ensures business logic only routes traffic for enabled channels.
  enabled Boolean

  /// Record creation timestamp - Implements audibility. Example: "2025-07-28T16:57:55+09:00". Never null; used in logs.
  created_at DateTime @db.Timestamptz

  /// Last modification timestamp. Used for sync and audit trails, not null. Updated on any change.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp - For retention/audit. If not null, channel is considered deleted. Satisfies compliance requirement for data retention/auditability.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  tenant ai_mall_backend_tenants @relation(fields: [tenant_id], references: [id], onDelete: Cascade)

  ai_mall_backend_sections       ai_mall_backend_sections[]
  ai_mall_backend_configurations ai_mall_backend_configurations[]
  ai_mall_backend_api_gateways   ai_mall_backend_api_gateways[]
  ai_mall_backend_carts          ai_mall_backend_carts[]
  ai_mall_backend_api_versions   ai_mall_backend_api_versions[]

  @@unique([code])
  @@unique([tenant_id, name])
  @@index([enabled])
  @@index([tenant_id, created_at])
  @@index([name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Section Entity - Implements extensible, dynamic business section management, mapping to a requirement for modular dynamic site/app composition. Each entry defines a logical section/component within a given channel context (e.g., home banner, product carousel, promo area). Maintains strict 3NF by referencing both channels and storing only section configuration here; layout/data references in auxiliary tables/materialized views if needed. Example: onboarding an app 'Main Banner' section for 'mobile' channel. Key relationships: references ai_mall_backend_channels; may be referenced by content/config tables elsewhere. Special behaviors: Can be dynamically enabled/disabled or scheduled, but schedules are not stored here.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_sections {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related channel's {@link ai_mall_backend_channels.id}; identifies which channel this section belongs to, ensuring no cross-channel confusion.
  channel_id String @db.Uuid

  /// Section code (domain-unique slug) - Used for programmatic reference. E.g., "main_banner", "featured_products". Meets normalization requirement: display name, config are not duplicated here.
  code String

  /// Display name for the section (for admin/UIs), e.g., "Main Banner". Atomic, not null. Used for search/UI, separated from configuration content.
  name String

  /// Logical activation flag for business scheduling. Required by dynamic rendering rules for channel UX composition. Must remain atomic; scheduling logic is externalized.
  enabled Boolean

  /// Creation timestamp for the section. Implements audit trail requirement. Not null.
  created_at DateTime @db.Timestamptz

  /// Change timestamp; always updated on row update. Not null. Used in auxiliary processing and audit logging.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion timestamp; null if not deleted, value set when removed for audit/compliance. Enforces audit/history policy.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel ai_mall_backend_channels @relation(fields: [channel_id], references: [id], onDelete: Cascade)

  ai_mall_backend_configurations ai_mall_backend_configurations[]

  @@unique([channel_id, code])
  @@index([channel_id, enabled])
  @@index([name])
}

/// Configuration Entity - Satisfies the requirements for a centralized configuration registry (feature toggles, branded settings, etc.). Each row specifies a single atomic configuration item, maintaining 3NF and not duplicating setting values. For instance, feature toggles, limits, branding variables, API keys (encrypted elsewhere). Relationships: references channel and optional section for scope; config values are always atomic. Usage example: enabling a feature in a specific section of the web channel. Special behaviors: Only stores atomic key-value data. Aggregates or computed/pre-resolved settings are handled in views/external caches.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Configured channel's {@link ai_mall_backend_channels.id}. Null if config is system-global. Maintains 2NF: channel-specific overrides do not duplicate global config data.
  channel_id String? @db.Uuid

  /// Configured section's {@link ai_mall_backend_sections.id}. Null if config is for entire channel.
  section_id String? @db.Uuid

  /// Config item name (machine-readable); enforced unique within channel/section scope. Normalized; avoids redundancy vs. human description. E.g., "max_recommended_items", "brand_accent_color".
  name String

  /// Config value (atomic). Storing as string makes it flexible for all config types. Atomic value by design—complex/aggregated representations handled outside core table. Example: "10", "#F47623", or JSON-encoded value. Enforces normalization: no multi-setting/storage.
  value String

  /// Description or business comment - For admin clarity and auditability. For example, "Controls max items on home banner". Not used in production logic, only as meta.
  description String?

  /// Creation timestamp - Satisfies audit/logging and change traceability.
  created_at DateTime @db.Timestamptz

  /// Modification timestamp; updated on any change. Implements audit trail requirement; not null.
  updated_at DateTime @db.Timestamptz

  /// Soft-deletion timestamp, null if still active. Enforces compliance/audit/max retention. Satisfies business policy for configuration sunset/reversion.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel ai_mall_backend_channels? @relation(fields: [channel_id], references: [id], onDelete: Cascade)
  section ai_mall_backend_sections? @relation(fields: [section_id], references: [id], onDelete: Cascade)

  @@unique([channel_id, section_id, name])
  @@index([section_id])
  @@index([name])
  @@index([channel_id])
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// API Gateway Entity - Implements registry of API gateway endpoints, configs, and associations (see Architecture requirements for API gateway concept). Each record defines an API endpoint, domain mapping, and metadata for routing/auth. Strict normalization—one entry per gateway/route, no calculated fields. For example, registering "api.mall.com/v2" as the main API route for the 'web' channel. Key relationships: references channel (for business context); referenced by tenant or system audit if required. Special behaviors: Gateway can be temporarily suspended/enabled, and settings beyond route are handled externally.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_api_gateways {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Target channel's {@link ai_mall_backend_channels.id}; ensures requests are mapped to the correct business context.
  channel_id String @db.Uuid

  /// Base route for this gateway (e.g., "/api/v1", "/mobile/"). Implements requirement for explicit, unambiguous routing. Atomic. No computed path fields stored here.
  route_base String

  /// Mapped domain for this gateway (FQDN or subdomain, e.g., "api.mall.com"). Per domain mapping, not null. No wildcard; each gateway registered separately. Used in endpoint discovery.
  domain String

  /// Gateway activation flag—allows quick suspension/reactivation. Only unaggregated atomic flag here.
  enabled Boolean

  /// Gateway creation time (audit/logs).
  created_at DateTime @db.Timestamptz

  /// Last config update timestamp (audit/tracking). Always required per system audit rules.
  updated_at DateTime @db.Timestamptz

  /// Soft-delete timestamp if gateway route is removed. Null means active. Complies with retention, audit policies.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  channel ai_mall_backend_channels @relation(fields: [channel_id], references: [id], onDelete: Cascade)

  @@unique([route_base, domain])
  @@index([enabled])
  @@index([channel_id])
  @@index([domain(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Tenant Entity - Implements the business requirement for full multi-tenancy isolation, as described in system architecture and compliance documents. Each row defines a distinct brand, sub-platform, or logical business tenant (e.g., for white-labeling, brand separation, regional variants). Design: strictly 3NF; all channel, user, and config references use tenant_id rather than duplicating brand/business info. For example, onboarding a new brand/partner, all data is tied to a unique tenant. Key relationships: referenced by channels, users, configurations, etc. Special behaviors: Tenant may be archived, not deleted, to maintain historical integrity.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_tenants {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Tenant code (unique per instance) - e.g., "main_mall", "brandA", "partner2". Used for programmatic routing and scoping. Normalized: display name/config not duplicated here.
  code String

  /// Display/business name of tenant (for admin/partner reference). Not null, atomic, normalized.
  name String

  /// Tenant archival flag—used for compliance, never hard-deletes. Implements regulatory retention. Example: true if tenant/brand offboarded.
  archived Boolean

  /// When this tenant/brand was onboarded. Used for onboarding processes, billing, audit.
  created_at DateTime @db.Timestamptz

  /// Last updated time; always atomic, not null, per audit policy.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_backend_channels ai_mall_backend_channels[]

  @@unique([code])
  @@unique([name])
  @@index([created_at])
}

schemas.schema-02-actors.prisma:
/// Customer actor entity - Implements requirements from the User Management and Role Definition documents, for tracking registered shoppers and their operational context. This model supports customer account onboarding, profile linkage, role enforcement (customer-only scope), and privacy compliance. Maintains 3NF by separating identity, credential, and role logic. For example, a typical customer uses this record as the root for shopping history, favorites, and personalization. Key relationships: main profile (user_profiles), credentials, roles. Special behaviors: deactivated or GDPR-erased accounts are soft-deleted but maintain audit trail.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_customers {
  //----
  // COLUMNS
  //----
  /// Primary Key. Uniquely identifies each customer record.
  id String @id @db.Uuid

  /// Associated user profile's {@link ai_mall_backend_user_profiles.id}. Connects this customer to their profile data for extensibility, privacy, and normalization.
  user_profile_id String @db.Uuid

  /// Customer's normalized, login/account email address - Implements authentication and notification requirements. Ensures account uniqueness and for privacy/audit linkage. Example: 'alice@customer.com'.
  email String

  /// Customer's primary contact phone - Implements phone-based auth/contact. Used for notifications and 2FA flows if enabled. Example: '+821012345678'.
  phone_number String?

  /// Creation timestamp for audit and lifecycle tracking. Ensures event traceability and compliance with audit/retention requirements. Example: '2025-07-01T10:00:00Z'.
  created_at DateTime @db.Timestamptz

  /// Soft deletion timestamp for account deactivation or privacy erasure. Ensures compliance with right-to-be-forgotten and lifecycle rules. Nullable, only present when account is deactivated.
  deactivated_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer_user_profile ai_mall_backend_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  ai_mall_backend_carts                    ai_mall_backend_carts[]
  ai_mall_backend_orders                   ai_mall_backend_orders[]
  ai_mall_backend_payments                 ai_mall_backend_payments[]
  ai_mall_backend_coupon_issuances         ai_mall_backend_coupon_issuances[]
  ai_mall_backend_coupon_usages            ai_mall_backend_coupon_usages[]
  ai_mall_backend_loyalty_point_ledgers    ai_mall_backend_loyalty_point_ledgers[]
  ai_mall_backend_point_usages             ai_mall_backend_point_usages[]
  ai_mall_backend_inquiries                ai_mall_backend_inquiries[]
  ai_mall_backend_inquiry_threads          ai_mall_backend_inquiry_threads[]
  ai_mall_backend_inquiry_attachments      ai_mall_backend_inquiry_attachments[]
  ai_mall_backend_reviews                  ai_mall_backend_reviews[]
  ai_mall_backend_review_comments          ai_mall_backend_review_comments[]
  ai_mall_backend_review_upvotes           ai_mall_backend_review_upvotes[]
  ai_mall_backend_review_snapshots         ai_mall_backend_review_snapshots[]
  ai_mall_backend_favorites                ai_mall_backend_favorites[]
  ai_mall_backend_favorite_snapshots       ai_mall_backend_favorite_snapshots[]
  ai_mall_backend_alerts                   ai_mall_backend_alerts[]
  ai_mall_backend_personalization_profiles ai_mall_backend_personalization_profiles?
  ai_mall_backend_recommendations          ai_mall_backend_recommendations[]

  @@unique([user_profile_id])
  @@unique([email])
  @@index([created_at])
}

/// Seller actor entity - Implements requirements for third-party vendors/partners as outlined in Role Definition and User Management modules. Maintains 3NF by isolating seller identity, profile, and access credentials. Used for product listing, order fulfillment, and analytics scoping. Example use: seller links to their shop's catalog and is constrained to their own data. Key relationships: main profile, credentials, roles. Special: Profile and role links ensure extensibility, audit, and privacy compliance.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_sellers {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for seller entity.
  id String @id @db.Uuid

  /// Associated user profile's {@link ai_mall_backend_user_profiles.id}. Seller-specific profile/data linkage, keeping schema normalized and extensible.
  user_profile_id String @db.Uuid

  /// Seller's unique business email for authentication/notification. Enforces account uniqueness and enables seller communications. Example: 'vendor@shop.com'.
  email String

  /// Seller's main contact number (SMS/2FA/app notifications). Allows seller-facing service notifications, alerts. Example: '+821099988877'.
  phone_number String?

  /// Creation timestamp for audit, onboarding, lifecycle events. Required for traceability and SLA compliance.
  created_at DateTime @db.Timestamptz

  /// Shop display title or entity name shown to customers. Implements branding and partner management requirement. Example: 'Seoul Style Socks'.
  shop_name String

  /// Soft deletion/deactivation timestamp for privacy/compliance lifecycle. Used for logical deletion or account erasure auditability.
  deactivated_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller_user_profile ai_mall_backend_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  ai_mall_backend_products ai_mall_backend_products[]
  ai_mall_backend_bundles  ai_mall_backend_bundles[]

  @@unique([user_profile_id])
  @@unique([email])
  @@index([created_at])
  @@index([shop_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Admin actor entity - Implements system/admin staff requirements from Role Management. Admins are responsible for platform governance, compliance, and audit. Maintains strict separation of identity, credentials, and assignment of elevated permissions. 3NF compliance is ensured by isolating references and not duplicating data from user_profile. Used for admin login, system event logging, and override actions. Special constraint: All actions must be audit-logged and are subject to multi-factor/secondary verification policies.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_admins {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for admin entity.
  id String @id @db.Uuid

  /// Associated user profile's {@link ai_mall_backend_user_profiles.id}. Centralizes admin profile data for compliance, multi-role support, and normalization.
  user_profile_id String @db.Uuid

  /// Admin's unique platform login email for authentication/contact. Used for notifications, escalation, and audit linkage. Example: 'admin@mall.com'.
  email String

  /// Account creation timestamp for audit/compliance slas, etc.
  created_at DateTime @db.Timestamptz

  /// Multi-factor authentication flag. Implements security policies requiring MFA on admin accounts. Example: true.
  mfa_enabled Boolean

  /// Account deactivation or soft deletion timestamp. Used for lifecycle management and compliance.
  deactivated_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  admin_user_profile ai_mall_backend_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  ai_mall_backend_review_moderation_logs ai_mall_backend_review_moderation_logs[]
  ai_mall_backend_audit_logs             ai_mall_backend_audit_logs[]
  ai_mall_backend_integration_keys       ai_mall_backend_integration_keys[]

  @@unique([user_profile_id])
  @@unique([email])
  @@index([created_at])
}

/// AI Agent actor entity - Implements requirements for internal AI-related service accounts, as per Role and User Management specs. AI agents execute automated operations such as recommendation, moderation, and risk detection. Keeps 3NF via clear separation of secrets, logic, and identity. Example: AI agent handles recommendation delivery with traceable reference to its actions. Key constraint: AI agent roles must be non-impersonable and strictly auditable.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_ai_agents {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for AI agent service account.
  id String @id @db.Uuid

  /// Associated user profile's {@link ai_mall_backend_user_profiles.id}. Allows extension, trace, and compliance normalization.
  user_profile_id String @db.Uuid

  /// Logical designation of this AI agent (e.g., 'recommender', 'moderator'). Supports programmatic routing and auditing. Example: 'ai_recommendations_worker'.
  service_name String

  /// Whether this AI Agent is active/allowed access. Implements automation workflow control; disables risky AI modules. Example: true.
  enabled Boolean

  /// Audit timestamp of last agency activity or automated workflow run. Used for operational monitoring and compliance.
  last_run_at DateTime? @db.Timestamptz

  /// Account/service creation timestamp for traceability and risk tracking.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_agent_user_profile ai_mall_backend_user_profiles @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  ai_mall_backend_alerts                   ai_mall_backend_alerts[]
  ai_mall_backend_personalization_profiles ai_mall_backend_personalization_profiles[]
  ai_mall_backend_recommendations          ai_mall_backend_recommendations[]

  @@unique([user_profile_id])
  @@unique([service_name])
  @@index([created_at])
}

/// Centralized user profile record - Implements profile normalization and extensibility requirements from the User Management module. Separates PII/contact data, roles, and personalization. Maintains 3NF by keeping profiles normalized and only referenced by actors. Usage: links multi-role identities (customer/seller/admin), supports privacy settings, consent management, and unified notification preferences. Special: Can be extended for new account types or compliance policies.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_user_profiles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Surrogate unique identifier for each profile record.
  id String @id @db.Uuid

  /// Preferred name or display alias for user. Implements personalization and privacy-friendly addressing. Example: 'Seungmin K.'.
  display_name String

  /// Profile avatar image link - used in account UX, personalization, and notifications. Example: 'https://cdn.mall.com/avatar/123.png'.
  avatar_url String? @db.VarChar(80000)

  /// User's unified consent for marketing communications. Enables privacy control and compliance rights. Example: false.
  consent_marketing Boolean

  /// User's preferred locale code (IETF language tag) for UI localization, content, default time zone. Example: 'ko-KR'.
  locale String

  /// User's preferred IANA timezone ID for notification and scheduling. Example: 'Asia/Seoul'.
  timezone String

  /// Profile creation timestamp for auditing and compliance logs.
  created_at DateTime @db.Timestamptz

  /// Profile last update timestamp for synchronization and event logs.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_backend_customers         ai_mall_backend_customers?
  ai_mall_backend_sellers           ai_mall_backend_sellers?
  ai_mall_backend_admins            ai_mall_backend_admins?
  ai_mall_backend_ai_agents         ai_mall_backend_ai_agents?
  ai_mall_backend_credentials       ai_mall_backend_credentials[]
  ai_mall_backend_product_snapshots ai_mall_backend_product_snapshots[]
  ai_mall_backend_product_evidence  ai_mall_backend_product_evidence[]

  @@unique([display_name, locale])
  @@index([created_at])
  @@index([updated_at])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Role definition reference - Implements core system role taxonomy as mandated in Roles documentation. Roles distinguish permission boundaries (customer, seller, admin, ai-agent). Normalized; not duplicated in user records. Used for RBAC enforcement, dynamic permission mapping, and auditing. 3NF is enforced by using only role_id foreign key everywhere. Example: Each account is assigned to one or more roles, centrally managed. Special: Adding or removing system roles may extend or restrict platform-wide behaviors.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_roles {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each role.
  id String @id @db.Uuid

  /// Role identifier (slug): 'customer', 'seller', 'admin', 'ai-agent' per platform spec. Implements security and permission boundary. Example: 'customer'.
  name String

  /// Human-readable description or system note about this role. For admins, documentation, and audit purpose. Example: 'Customer: can shop and manage own account only.'
  description String?

  /// Timestamp recorded at role creation for audit, compliance.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_backend_order_status_logs ai_mall_backend_order_status_logs[]
  ai_mall_backend_order_snapshots   ai_mall_backend_order_snapshots[]

  @@unique([name])
  @@index([created_at])
}

/// Authentication provider record - Implements modular extensibility and multi-provider support as required by the User Management module. Providers represent supported login methods (email, oauth, service-token, etc). 3NF compliant; avoids duplication in user/credential tables. Example: 'email_password', 'google', 'kakao', 'service_token'. Special: Adding new providers is possible without schema rewrite. Each credential links to one provider by foreign key, enforcing modularity.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_auth_providers {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique ID for each supported auth provider.
  id String @id @db.Uuid

  /// Provider type (slug): ENUM: 'email_password', 'social_google', 'social_facebook', 'social_kakao', 'service_token', etc. Value must strictly match app logic and UI. Used for mapping credentials to login flows. Example: 'email_password'.
  type String

  /// Provider label or human-friendly display value (UI purposes). Example: 'Google', 'Kakao'.
  display_name String

  /// Provider creation timestamp (for auditing, history, and migration).
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  ai_mall_backend_credentials ai_mall_backend_credentials[]

  @@unique([type])
  @@index([created_at])
}

/// Authentication credential record - Implements credential storage/assignment to actors via normalization principles (3NF). Each credential is scoped to a single provider (foreign key), and a user actor (customer, seller, admin, ai-agent) by profile/user-specific fields. Password hashes, oauth tokens, or service tokens are stored per security best practices. Credentials may be soft-deleted (revoked) for audit and compliance. Example: Each login method for an account (email, google, service-token) is a separate row. On credential failure/expiry, can be revoked without deleting user. Key: Enforces modular and extensible credentialing without schema rewrite.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_credentials {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for this credential row.
  id String @id @db.Uuid

  /// Linked authentication provider's {@link ai_mall_backend_auth_providers.id}. Cleanly separates provider logic from credentialing; critical to modularity and system upgrade.
  auth_provider_id String @db.Uuid

  /// Linked user profile's {@link ai_mall_backend_user_profiles.id}. Ties sensitive credential info to the correct actor. Ensures privacy and audit compliance.
  user_profile_id String @db.Uuid

  /// Provider-unique identifier (e.g., email, social ID, service token ID). Must match unique constraint for provider/user combination. Example: 'alice@example.com', 'kakao_oauth_123456'.
  identifier String

  /// Stored secret (password hash, OAuth token, service token). Value is hashed/salted/encrypted depending on provider logic. Managed via security policy. Example: '$argon2id$v=19$m=4096,t=3,p=1$...'.
  credential_secret String

  /// Credential creation timestamp, required for audit and compliance with rotation/expiry policies.
  created_at DateTime @db.Timestamptz

  /// Timestamp for soft deletion/revocation. Present if credential is expired, rotated, or invalidated for cause.
  revoked_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  credential_auth_provider ai_mall_backend_auth_providers @relation(fields: [auth_provider_id], references: [id], onDelete: Cascade)
  credential_user_profile  ai_mall_backend_user_profiles  @relation(fields: [user_profile_id], references: [id], onDelete: Cascade)

  @@unique([auth_provider_id, identifier])
  @@index([user_profile_id])
  @@index([created_at])
  @@index([identifier(ops: raw("gin_trgm_ops"))], type: Gin)
}

schemas.schema-03-products.prisma:
/// Product core record - Implements the requirement for product lifecycle and catalog entity from the product management requirements document. Handles all basic product attributes including base title, SKU, status, seller links, pricing method, and configuration. Maintains strict 3NF by putting only atomic product data here. For example, used when a seller creates or updates a product listing. Key relationships: Snapshots for versioning, variants for SKUs, bundles for grouped sales. Special behaviors: Soft-deletion for archiving and audit. No denormalized totals or AI-aggregated data.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_products {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each product.
  id String @id @db.Uuid

  /// Belonged seller's {@link ai_mall_backend_sellers.id}. Links the product to its owning vendor. Required reference for all products.
  seller_id String @db.Uuid

  /// Product SKU - Implements SKU tracking requirement. Unique seller-assigned code for warehouse and catalog operations. Ensures normalization by placement in core product record only. Example: 'SKU-202508-001'. No nulls allowed.
  sku String

  /// Main product title - Implements product naming and navigation requirement. Set by the seller or AI enrichment. For example, 'Wireless Headphones Pro'. Required.
  title String

  /// Full product description - Allows detailed information for browsing, search, and AI recommendations. Ensures normalization by only including product-level description (detailed variant/content in linked entities). Example: 'Premium noise-cancelling...'. Required.
  description String

  /// Base product price (default variant or minimum) - Atomic monetary value for pricing. For example, 299.0. Not a calculated total, strictly normalized.
  price Float @db.DoublePrecision

  /// Tax class identifier - Associates correct tax calculation/service in normalized manner. Ensures 3NF.
  tax_class String

  /// Inventory tracking strategy string. Implements inventory method specification. For example, 'per_variant', 'none', or custom. Keeps normalization by avoiding derived or status fields.
  inventory_method String

  /// Product status code - e.g. 'active', 'archived', 'pending'. Used for workflow control, archiving, and AI enrichment. No aggregation or denormalization.
  status String

  /// Created timestamp - Implements history/audit control. Example: 2025-07-28T07:57:55.559Z. Immutable.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp. Ensures temporal normalization and auditing. Required for business process tracking.
  updated_at DateTime @db.Timestamptz

  /// Soft-delete timestamp. Null if not deleted; used for retention compliance. Normalized deletion, not a status indicator.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_products_seller_id ai_mall_backend_sellers @relation(fields: [seller_id], references: [id], onDelete: Cascade)

  ai_mall_backend_product_snapshots  ai_mall_backend_product_snapshots[]
  ai_mall_backend_variants           ai_mall_backend_variants[]
  ai_mall_backend_category_products  ai_mall_backend_category_products[]
  ai_mall_backend_product_evidence   ai_mall_backend_product_evidence[]
  ai_mall_backend_product_media      ai_mall_backend_product_media[]
  ai_mall_backend_cart_items         ai_mall_backend_cart_items[]
  ai_mall_backend_order_items        ai_mall_backend_order_items[]
  ai_mall_backend_inquiries          ai_mall_backend_inquiries[]
  ai_mall_backend_reviews            ai_mall_backend_reviews[]
  ai_mall_backend_favorites          ai_mall_backend_favorites[]
  ai_mall_backend_favorite_snapshots ai_mall_backend_favorite_snapshots[]
  ai_mall_backend_alerts             ai_mall_backend_alerts[]
  ai_mall_backend_recommendations    ai_mall_backend_recommendations[]

  @@unique([sku, seller_id])
  @@index([seller_id])
  @@index([created_at])
  @@index([status])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Product snapshot records - Implements audit, history, and versioning per snapshot pattern from requirements. Saves all critical product state changes with before/after data, actor, reason, and timestamp. Ensures 3NF by separating history from current product record. Example: Used during product update, AI enrichment, or admin change. Key relationship: Linked to a product; immutable records.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_product_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each snapshot.
  id String @id @db.Uuid

  /// Source product's {@link ai_mall_backend_products.id}. The product this snapshot version applies to.
  product_id String @db.Uuid

  /// Actor's user id responsible for snapshot (customer/admin/seller/ai-agent). Links to user entities in actors namespace (not duplicated).
  actor_id String @db.Uuid

  /// Reason for snapshot - Audit and traceability. E.g., 'Price changed by Seller', 'AI auto-enrichment', 'Category change'. Maintains normalization by not embedding product fields here.
  snapshot_reason String

  /// Full serialized state of product for audit/version rollback. Typically JSON or binary format. Example: '{"sku":...}'. Not denormalized, but a point-in-time immutable fact. Not a duplicated product field.
  snapshot_data String

  /// Snapshot creation timestamp. Used for version ordering, retention policy, and rollback audit trail. Required.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_product_snapshots_product_id ai_mall_backend_products      @relation(fields: [product_id], references: [id], onDelete: Cascade)
  fk_product_snapshots_actor_id   ai_mall_backend_user_profiles @relation(fields: [actor_id], references: [id], onDelete: Cascade)

  ai_mall_backend_product_evidence ai_mall_backend_product_evidence[]

  @@index([product_id])
  @@index([actor_id])
}

/// Product variant (option/child SKU) entity - Implements product variant and option design. Each variant represents a unique SKU with its own price, attributes, and inventory linkage. Maintains 3NF by storing only variant-specific atomic data. For example, 'Color: Red, Size: L'. Relates to parent product, inventory, and bundles. Variants are child SKUs, key for multi-option products.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_variants {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each variant.
  id String @id @db.Uuid

  /// Parent product's {@link ai_mall_backend_products.id}. The core product this variant is part of.
  product_id String @db.Uuid

  /// Variant-specific SKU - Implements accurate warehouse and transaction handling per child SKU. Ensures strict normalization. Example: 'SKU-202508-001-RED-L'. Not null.
  sku String

  /// JSON-encoded selected option values for this variant (e.g., color/size/material). Maintains 3NF by representing configuration atomically. Example: '{"Color":"Red","Size":"L"}'. Not denormalized; not a reference array.
  option_values String

  /// Variant price - Atomic monetary value; never a total or derived from bundle/other variants. Strictly normalized. Example: 329.99.
  price Float @db.DoublePrecision

  /// Variant status, e.g., 'active', 'unavailable'. Follows workflow/state transitions and ensures normalization. Not derived/calculated.
  status String

  /// Created timestamp (for variant). Used for audit history, not aggregation. Example: 2025-07-28T07:57:55.559Z.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for variant, for audit and rollback. Not derived/calculated.
  updated_at DateTime @db.Timestamptz

  /// Soft-delete timestamp (null if active). Allows compliance retention and proper archival. Strictly normalized; not a status field.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_variants_product_id ai_mall_backend_products @relation(fields: [product_id], references: [id], onDelete: Cascade)

  ai_mall_backend_inventory       ai_mall_backend_inventory[]
  ai_mall_backend_bundle_products ai_mall_backend_bundle_products[]
  ai_mall_backend_product_media   ai_mall_backend_product_media[]
  ai_mall_backend_cart_items      ai_mall_backend_cart_items[]
  ai_mall_backend_order_items     ai_mall_backend_order_items[]

  @@unique([sku, product_id])
  @@index([product_id])
  @@index([status])
}

/// Junction table for products-to-categories (M:N) - Implements many-to-many relationship per requirements for flexible product navigation and categorization. Each row links one product to one category, maintaining 3NF. Used when a product needs to be classified under multiple categories or a category contains multiple products. No denormalized/aggregate fields included.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_category_products {
  //----
  // COLUMNS
  //----
  /// Primary key for association row. Unique identifier for each product-category relationship.
  id String @id @db.Uuid

  /// Product's {@link ai_mall_backend_products.id} in category.
  product_id String @db.Uuid

  /// Category's {@link ai_mall_backend_categories.id} this product maps to.
  category_id String @db.Uuid

  /// Timestamp when product was categorized. For audit trail and rollback, not summary/aggregation.
  assigned_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  fk_category_products_product_id  ai_mall_backend_products   @relation(fields: [product_id], references: [id], onDelete: Cascade)
  fk_category_products_category_id ai_mall_backend_categories @relation(fields: [category_id], references: [id], onDelete: Cascade)

  @@unique([product_id, category_id])
  @@index([category_id])
}

/// Product category reference - Implements flexible, hierarchical category navigation requirement. Allows parent/child category relationships, merchandising metadata, and AI enrichment per requirements. Maintains normalization by only including atomic details. Example: 'Electronics > Headphones'. Key relationships: Products via category_products, parent category (if any). Special behaviors: No denormalized product counts in this entity.
///
/// @namespace Products
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_categories {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for each category.
  id String @id @db.Uuid

  /// Self-reference to parent category's {@link ai_mall_backend_categories.id}. Enables multi-level hierarchy. Nullable for root categories.
  parent_id String? @db.Uuid

  /// Unique category code for API reference and integration. Maintains normalization by using code instead of category-derived meanings. Example: 'ELEC-HEADPHONES'.
  code String

  /// Category name for UI and navigation. Example: 'Headphones'. Not a denormalized count or string.
  name String

  /// Long-form category description for merchant and AI enrichment. Maintains 3NF. Example: 'All headphone products, including wireless and wired.'
  description String?

  /// URI to representative image/icon for merchandising. Atomic link field. Example: 'https://cdn.example.com/cat/electronics.jpg'.
  image_uri String? @db.VarChar(80000)

  /// Optional merchandising badge or icon string. Not used for computed/generative info. Example: 'Best Seller'.
  badge String?

  /// Optional ranking integer for explicit category ordering (not an aggregate count).
  ranking Int? @db.Integer

  /// Created timestamp for category, used for audit and versioning.
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for the category.
  updated_at DateTime @db.Timestamptz

  /// Soft-deleted timestamp for category if archived. Null if active. Used for compliance, not as a status field.
