schemas.schema-04-carts.prisma:
/// Cart - Implements the cart entity required for multi-channel, tenant-aware, user-specific shopping cart management with full audit trail, session/channel separation, and soft-deletion support. This is in strict 3NF; all pre-calculated data is excluded. All attributes and relationships adhere to the business and normalization requirements outlined in the order fulfillment (04_ai-mall-backend_order-fulfillment.md) and audit logging modules.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_carts {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for a cart.
  id String @id @db.Uuid

  /// Belonged customer's {@link ai_mall_backend_customers.id}. Associates a cart with its owner for all customer-specific operations and analytics.
  ai_mall_backend_customer_id String @db.Uuid

  /// Channel context's {@link ai_mall_backend_channels.id}. Associates each cart with a particular channel for proper segregation and fulfillment routing.
  ai_mall_backend_channel_id String @db.Uuid

  /// Timestamp cart was created, for lifecycle and audit tracking.
  created_at DateTime @db.Timestamptz

  /// Timestamp for most recent update to the cart, for change history and business process compliance.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when cart was marked as abandoned. Null if not abandoned; used for journey analytics and retention workflows.
  abandoned_at DateTime? @db.Timestamptz

  /// Soft deletion timestamp. Null if active; required for retention, auditability, and compliance purposes.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer ai_mall_backend_customers @relation(fields: [ai_mall_backend_customer_id], references: [id], onDelete: Cascade)
  channel  ai_mall_backend_channels  @relation(fields: [ai_mall_backend_channel_id], references: [id], onDelete: Cascade)

  ai_mall_backend_cart_items     ai_mall_backend_cart_items[]
  ai_mall_backend_cart_snapshots ai_mall_backend_cart_snapshots[]

  @@unique([ai_mall_backend_customer_id, ai_mall_backend_channel_id], map: "ai_mall_backend_carts_ai_mall_backend_customer_id_ai_m_bfc76316")
  @@index([ai_mall_backend_channel_id])
  @@index([created_at])
  @@index([updated_at])
}

/// Cart Item - Each itemized record in the cart tied to a specific product, variant, and/or bundle. Strict 3NF compliance—no calculated fields, all pricing/summary data is deferred to order calculation or materialized views. Required for traceable, atomic management of shopping cart contents with soft-deletion for abandoned/recovered cart item handling.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_cart_items {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for a cart item record.
  id String @id @db.Uuid

  /// Parent cart's {@link ai_mall_backend_carts.id}. Enables grouping all items by cart for order/batch actions.
  ai_mall_backend_cart_id String @db.Uuid

  /// Product's {@link ai_mall_backend_products.id}. Foreign key for analytics and item validation. Required for every cart item.
  ai_mall_backend_product_id String @db.Uuid

  /// Variant's {@link ai_mall_backend_variants.id} (nullable for non-variant items). Enables option/variant-level granularity; null if not a variant SKU.
  ai_mall_backend_variant_id String? @db.Uuid

  /// If the item is part of a bundle: {@link ai_mall_backend_bundles.id} (nullable). Supports per-bundle itemization; null otherwise.
  ai_mall_backend_bundle_id String? @db.Uuid

  /// Atomically tracked number of units for this item in the cart. Direct input, strictly atomic, not a calculated value.
  quantity Int @db.Integer

  /// Timestamp this item was added, for audit and analytics.
  added_at DateTime @db.Timestamptz

  /// Last update timestamp for this item.
  updated_at DateTime @db.Timestamptz

  /// Soft deletion timestamp, supporting recovery/auditing of cart items. Null if active.
