  @@unique([ai_mall_backend_cart_id, ai_mall_backend_product_id, ai_mall_backend_variant_id, ai_mall_backend_bundle_id], map: "ai_mall_backend_cart_items_ai_mall_backend_cart_id_ai__19c0064b")
  @@index([ai_mall_backend_product_id])
  @@index([ai_mall_backend_variant_id])
  @@index([ai_mall_backend_bundle_id])
  @@index([ai_mall_backend_cart_id])
  @@index([added_at])
}

/// Cart Snapshot - Temporal/audit entity for history and analytics of cart state transitions. Strictly normalized; stores event, state-as-JSON, and timestamp with reference to the source cart. Read-only/append-only log for full auditability and evidence in compliance, rollback, and analytics scenarios.
///
/// @namespace Carts
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model ai_mall_backend_cart_snapshots {
  //----
  // COLUMNS
  //----
  /// Primary Key. Unique identifier for this snapshot event.
