  description String?

  /// Discount type: 'percentage', 'fixed', 'freeship', etc. (enum supported at logic level).
  discount_type String

  /// Stored discount value, interpreted per discount_type field. Atomic value, never a calculation result.
  discount_value Float @db.DoublePrecision

  /// Minimum required spend for use of coupon to be eligible.
  minimum_spend Float @db.DoublePrecision

  /// Start date/time of coupon validity window.
  valid_from DateTime @db.Timestamptz

  /// End date/time of coupon validity window.
  valid_until DateTime @db.Timestamptz

  /// Maximum allowed redemptions per user.
  max_uses_per_user Int? @db.Integer

  /// Total redemption cap for coupon across all users.
  total_redemption_limit Int? @db.Integer

  /// Whether coupon is currently enabled/allowed for issuance/redemption.
  is_active Boolean

  /// Row creation timestamp for audit.
  created_at DateTime @db.Timestamptz

  /// Row update timestamp for audit.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  campaign ai_mall_backend_campaigns? @relation(fields: [ai_mall_backend_campaign_id], references: [id], onDelete: Cascade)

  ai_mall_backend_coupon_issuances ai_mall_backend_coupon_issuances[]

