 *
 * [테스트 시나리오]
 *
 * 1. Code와 name이 각각 다른 두 개의 테넌트를 생성한다.
 * 2. 첫 번째 테넌트의 code를 두 번째 테넌트의 code와 동일하게 바꾸는 업데이트 요청을 보내고, 고유성 위반 에러가 나는지 확인한다.
 * 3. 첫 번째 테넌트의 name을 두 번째 테넌트의 name과 동일하게 바꾸는 업데이트 요청을 보내고, 고유성 위반 에러가 나는지 확인한다.
 */
export async function test_api_aiMallBackend_tenants_test_update_tenant_with_duplicate_code_or_name(
  connection: api.IConnection,
) {
  // 1. 서로 다른 두 개의 테넌트 생성
  const tenant1 = await api.functional.aiMallBackend.tenants.create(
    connection,
    {
