    {
      body: {
        code: RandomGenerator.alphaNumeric(8),
        name: RandomGenerator.paragraph()(1),
        archived: false,
      } satisfies IAiMallBackendTenants.ICreate,
    },
  );
  typia.assert(tenant2);
  TestValidator.notEquals("테넌트 code 불일치 확인")(tenant1.code)(
    tenant2.code,
  );
  TestValidator.notEquals("테넌트 name 불일치 확인")(tenant1.name)(
    tenant2.name,
  );

  // 2. tenant1의 code를 tenant2의 code로 바꾸는 업데이트 시도 (중복코드)
  await TestValidator.error("code 중복 업데이트 시 에러반환")(() =>
    api.functional.aiMallBackend.tenants.update(connection, {
