    api.functional.aiMallBackend.tenants.update(connection, {
      id: tenant1.id,
      body: {
        code: tenant1.code,
        name: tenant2.name,
        archived: tenant1.archived,
      } satisfies IAiMallBackendTenants.IUpdate,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
