/**
 * Validate pagination of ai_mall_backend_configurations records.
 *
 * This test checks that the paginated configuration listing endpoint correctly
 * slices a dataset that exceeds a single page, validating record limit and
 * truncation logic as controlled by the backend's default limit. Direct control
 * of page/limit is not supported by the DTO/API, so only first-page queries and
 * default truncation are asserted.
 *
 * Process:
 *
 * 1. Create N = (default page size + extra) configuration rows using unique
 *    deterministic names.
 * 2. Retrieve first result page (with empty filter), assert that only default page
 *    size configs are returned (e.g. 20).
 * 3. Assert that only the first N configs are present, that returned count matches
 *    page size, and that the returned results match expected order/truncation.
 *
 * This ensures the endpoint does not over-return records, correctly truncates
 * responses, and signals server-side paging works as intended up to the default
 * limit. Deep navigation to subsequent pages cannot be tested due to lack of
 * request params in the current API contract.
 */
export async function test_api_aiMallBackend_configurations_test_pagination_of_configuration_results(
  connection: api.IConnection,
) {
  // Assumed default page size (as is common, typically 20; adjust if doc specifies)
  const PAGE_SIZE = 20;
  const TOTAL = PAGE_SIZE + 5;

  // 1. Create TOTAL deterministic unique configuration records
  const configs: IAiMallBackendConfigurations[] = [];
  for (let i = 0; i < TOTAL; ++i) {
    const created = await api.functional.aiMallBackend.configurations.create(
      connection,
      {
        body: {
          name: `test-pagination-config-${i}`,
          value: `v${i}`,
          description: `pagination test record #${i}`,
        } satisfies IAiMallBackendConfigurations.ICreate,
      },
    );
    typia.assert(created);
    configs.push(created);
  }

  // Sort for expected order (descending by created_at, to match typical backend default)
  const expectedSorted = [...configs].sort((a, b) =>
    a.created_at > b.created_at ? -1 : 1,
  );

  // 2. Retrieve first page (assume empty filter; default page/limit applies)
  const page1 = await api.functional.aiMallBackend.configurations.index(
    connection,
    {
      body: {} satisfies IAiMallBackendConfigurations.IRequest,
    },
  );
  typia.assert(page1);

  // Validate record count and expected presence (default: PAGE_SIZE)
  TestValidator.equals("first page count")(page1.data.length)(PAGE_SIZE);

  const page1Ids = new Set(page1.data.map((x) => x.id));
  for (const id of expectedSorted.slice(0, PAGE_SIZE).map((c) => c.id)) {
    TestValidator.predicate("first page contains expected config")(
      page1Ids.has(id),
    );
  }
  // (No subsequent pages can be retrieved: API does not support page navigation)

  // Validate ordering (descending created_at)
  for (let i = 0; i < page1.data.length - 1; ++i) {
    const left = page1.data[i].created_at;
    const right = page1.data[i + 1].created_at;
    TestValidator.predicate("descending created_at order")(left >= right);
  }

  // Check pagination metadata for first page
  TestValidator.equals("metadata: first page")(page1.pagination.current)(1);
  TestValidator.equals("metadata: page size")(page1.pagination.limit)(
    PAGE_SIZE,
  );
  TestValidator.equals("metadata: total records")(page1.pagination.records)(
    TOTAL,
  );
  TestValidator.equals("metadata: number of pages")(page1.pagination.pages)(2);
}

