import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiMallBackendConfigurations } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiMallBackendConfigurations";

/**
 * Validate soft-delete behavior for ai_mall_backend_configurations.
 *
 * This test ensures that when a configuration is soft-deleted via the DELETE
 * /aiMallBackend/configurations/{id} endpoint, the 'deleted_at' field is set to
 * a non-null current timestamp in the result, confirming the row is archived
 * rather than physically removed.
 *
 * Steps:
 *
 * 1. Create a configuration with required fields (using POST
 *    /aiMallBackend/configurations).
 * 2. Soft-delete the configuration using DELETE
 *    /aiMallBackend/configurations/{id}.
 * 3. Assert that the returned result includes a 'deleted_at' value (non-null and
 *    in date-time format).
 * 4. Check that all other fields remain unchanged except for 'deleted_at' and
 *    'updated_at'.
 */
export async function test_api_aiMallBackend_configurations_test_soft_delete_configuration_and_verify_deleted_at_set(
  connection: api.IConnection,
) {
  // 1. Create a configuration row for deletion test
  const configCreateInput: IAiMallBackendConfigurations.ICreate = {
    name: `config_delete_test_${RandomGenerator.alphaNumeric(8)}`,
    value: "test-value",
    // Optionals: leave null to verify default handling
    channel_id: null,
    section_id: null,
    description: null,
  };
  const configuration =
    await api.functional.aiMallBackend.configurations.create(connection, {
      body: configCreateInput,
    });
  typia.assert(configuration);
  TestValidator.equals("deleted_at on create should be null")(
    configuration.deleted_at,
  )(null);

  // 2. Soft-delete the configuration
  const deletedConfig = await api.functional.aiMallBackend.configurations.erase(
    connection,
    { id: configuration.id },
  );
  typia.assert(deletedConfig);

  // 3. Verify 'deleted_at' is set (i.e., not null and date-time string)
  TestValidator.predicate("deleted_at is set after erase")(
    typeof deletedConfig.deleted_at === "string" && !!deletedConfig.deleted_at,
  );

  // 4. Ensure unchanged fields (except deleted_at and updated_at)
  TestValidator.equals("id unchanged after delete")(deletedConfig.id)(
    configuration.id,
  );
  TestValidator.equals("name unchanged after delete")(deletedConfig.name)(
    configuration.name,
  );
  TestValidator.equals("value unchanged after delete")(deletedConfig.value)(
    configuration.value,
  );
  TestValidator.equals("channel_id unchanged after delete")(
    deletedConfig.channel_id,
  )(configuration.channel_id);
  TestValidator.equals("section_id unchanged after delete")(
    deletedConfig.section_id,
  )(configuration.section_id);
  TestValidator.equals("description unchanged after delete")(
    deletedConfig.description,
  )(configuration.description);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiMallBackendConfigurations } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiMallBackendConfigurations";

/**
 * Validate that attempting to soft-delete a configuration that is already
 * deleted returns an error.
 *
 * This test function ensures that if a configuration (in
 * ai_mall_backend_configurations) has already been soft-deleted (i.e., its
 * deleted_at field is not null), attempting to soft-delete it again will result
 * in an error as expected by the business rules.
 *
 * Steps:
 *
 * 1. Create a configuration using the create API with valid random data.
 * 2. Soft-delete the configuration by calling erase with its id.
 *
 *    - Confirm that deleted_at is set, marking the record as soft-deleted.
 * 3. Attempt to soft-delete the same configuration again.
 *
 *    - This should fail; the API should return an error, which is validated.
 */
export async function test_api_aiMallBackend_configurations_test_soft_deleting_already_deleted_configuration_errors(
  connection: api.IConnection,
) {
  // 1. Create a configuration
  const config = await api.functional.aiMallBackend.configurations.create(
    connection,
    {
      body: {
        name: RandomGenerator.alphaNumeric(8),
        value: RandomGenerator.alphaNumeric(15),
        description: RandomGenerator.paragraph()(),
        channel_id: null,
        section_id: null,
      } satisfies IAiMallBackendConfigurations.ICreate,
    },
  );
  typia.assert(config);

  // 2. Soft-delete the configuration
  const erased = await api.functional.aiMallBackend.configurations.erase(
    connection,
    {
      id: config.id,
    },
  );
  typia.assert(erased);
  TestValidator.predicate("deleted_at is set after erase")(!!erased.deleted_at);

  // 3. Attempt to soft-delete again and expect error
  await TestValidator.error("double soft-delete should error")(() =>
    api.functional.aiMallBackend.configurations.erase(connection, {
      id: config.id,
    }),
  );
}

