import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiMallBackendChannels } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiMallBackendChannels";
import type { IAiMallBackendSections } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiMallBackendSections";

/**
 * Validate creation of a new section tied to a valid business channel, with all
 * mandatory fields supplied.
 *
 * This test is required to confirm that the platform supports modular content
 * management (section composition) in a multi-tenant, multi-channel context. A
 * section cannot exist without an associated channel, enforcing strong foreign
 * key constraints and modular design. Timestamp attributes must be set for
 * audit trail.
 *
 * Test Procedure:
 *
 * 1. Create a business channel with all required properties.
 * 2. Use its id as channel_id to create a new section, providing code, name, and
 *    enabled=true/false.
 * 3. Validate the returned section record matches input and business rules, and
 *    audit columns (created_at, updated_at) are set to valid date-time
 *    strings.
 */
export async function test_api_aiMallBackend_test_create_section_with_valid_channel_and_full_data(
  connection: api.IConnection,
) {
  // 1. Create a channel as a required dependency for the section
  const tenantId = typia.random<string & tags.Format<"uuid">>();
  const channelCode = RandomGenerator.alphaNumeric(8);
  const channelName = RandomGenerator.alphabets(10);
  const channelEnabled = true;

  const channel = await api.functional.aiMallBackend.channels.create(
    connection,
    {
      body: {
        tenant_id: tenantId,
        code: channelCode,
        name: channelName,
        enabled: channelEnabled,
      } satisfies IAiMallBackendChannels.ICreate,
    },
  );
  typia.assert(channel);
  TestValidator.equals("channel code")(channel.code)(channelCode);
  TestValidator.equals("channel tenant_id")(channel.tenant_id)(tenantId);
  TestValidator.equals("channel enabled")(channel.enabled)(channelEnabled);
  TestValidator.predicate("valid created_at timestamp")(
    !!Date.parse(channel.created_at),
  );
  TestValidator.predicate("valid updated_at timestamp")(
    !!Date.parse(channel.updated_at),
  );
  TestValidator.equals("channel deleted_at is null or undefined")(
    channel.deleted_at ?? null,
  )(null);

  // 2. Create a new section under this channel
  const sectionCode = RandomGenerator.alphaNumeric(6);
  const sectionName = RandomGenerator.alphabets(15);
  const sectionEnabled = true;
  const section = await api.functional.aiMallBackend.sections.create(
    connection,
    {
      body: {
        channel_id: channel.id,
        code: sectionCode,
        name: sectionName,
        enabled: sectionEnabled,
      } satisfies IAiMallBackendSections.ICreate,
    },
  );
  typia.assert(section);
  TestValidator.equals("section channel_id")(section.channel_id)(channel.id);
  TestValidator.equals("section code")(section.code)(sectionCode);
  TestValidator.equals("section name")(section.name)(sectionName);
  TestValidator.equals("section enabled")(section.enabled)(sectionEnabled);
  TestValidator.predicate("section created_at timestamp valid")(
    !!Date.parse(section.created_at),
  );
  TestValidator.predicate("section updated_at timestamp valid")(
    !!Date.parse(section.updated_at),
  );
  TestValidator.equals("section deleted_at is null or undefined")(
    section.deleted_at ?? null,
  )(null);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiMallBackendSections } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiMallBackendSections";

/**
 * Validate error handling for creating a section with an invalid channel
 * association (referential integrity enforcement)
 *
 * This test ensures that the API correctly rejects the creation of a new
 * ai_mall_backend_sections record when the supplied channel_id does not
 * correspond to an existing or enabled ai_mall_backend_channels entry. This
 * maintains foreign key integrity and prevents business logic errors from
 * orphaned or invalid section references. The system must respond with an error
 * rather than creating the section.
 *
 * Steps:
 *
 * 1. Generate a random UUID to simulate a non-existent channel_id (not present in
 *    channels table)
 * 2. Construct a valid IAiMallBackendSections.ICreate object, but set the
 *    channel_id to this invalid value
 * 3. Attempt to create the section via the create API
 * 4. Assert that the API responds with an error (e.g., referential integrity
 *    violation, invalid foreign key, or business logic error)
 * 5. Verify that no section is actually created and that the error is properly
 *    formatted according to API contract
 */
export async function test_api_aiMallBackend_test_create_section_with_invalid_channel_id(
  connection: api.IConnection,
) {
  // 1. Generate a random non-existent/deleted channel_id
  const invalidChannelId: string = typia.random<string & tags.Format<"uuid">>();

  // 2. Construct section creation data with invalid channel_id
  const sectionData = {
    channel_id: invalidChannelId,
    code: "invalid_test_section",
    name: "Section with invalid channel association",
    enabled: true,
  } satisfies IAiMallBackendSections.ICreate;

  // 3. Attempt to create section and 4. Assert on error
  await TestValidator.error("should fail with invalid channel_id")(() =>
    api.functional.aiMallBackend.sections.create(connection, {
      body: sectionData,
    }),
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiMallBackendChannels } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiMallBackendChannels";
import type { IAiMallBackendSections } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiMallBackendSections";

/**
 * 테스트 목적: 동일 채널 내에서 section code의 유일성 제약이 정확히 강제되는지 검증합니다.
 *
 * 시나리오:
 *
 * 1. 유효한 비즈니스 채널(ai_mall_backend_channels)을 생성합니다.
 * 2. 해당 채널에 고유한 code로 section(ai_mall_backend_sections)을 생성합니다.
 * 3. 동일 채널에서 같은 code로 두 번째 section 생성 시도를 합니다.
 * 4. API가 code 중복으로 에러를 반환하는지 TestValidator.error로 검증합니다. 이로써 채널별 section code 유일성
 *    제약이 올바르게 적용되는지 확인할 수 있습니다.
 */
export async function test_api_aiMallBackend_sections_test_create_section_with_duplicate_code_in_same_channel(
  connection: api.IConnection,
) {
  // 1. 유효한 채널 생성
  const channelInput: IAiMallBackendChannels.ICreate = {
    tenant_id: typia.random<string & tags.Format<"uuid">>(),
    code: RandomGenerator.alphaNumeric(8),
    name: RandomGenerator.paragraph()(),
    enabled: true,
  };
  const channel = await api.functional.aiMallBackend.channels.create(
    connection,
    { body: channelInput },
  );
  typia.assert(channel);

  // 2. 해당 채널에 고유 code로 section 생성
  const sectionCode = RandomGenerator.alphaNumeric(6);
  const sectionInput: IAiMallBackendSections.ICreate = {
    channel_id: channel.id,
    code: sectionCode,
    name: RandomGenerator.paragraph()(),
    enabled: true,
  };
  const section = await api.functional.aiMallBackend.sections.create(
    connection,
    { body: sectionInput },
  );
  typia.assert(section);

  // 3. 동일 채널, 동일 code로 두 번째 section 생성 시도 (유일성 위반)
  const duplicateSectionInput: IAiMallBackendSections.ICreate = {
    channel_id: channel.id,
    code: sectionCode, // 중복 코드!
    name: RandomGenerator.paragraph()(),
    enabled: true,
  };
  await TestValidator.error("동일 채널 내 section code 중복시 에러 반환됨")(
    async () => {
      await api.functional.aiMallBackend.sections.create(connection, {
        body: duplicateSectionInput,
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiMallBackendChannels } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiMallBackendChannels";
import type { IAiMallBackendSections } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiMallBackendSections";

/**
 * Validate input validation logic for section creation by omitting required
 * fields.
 *
 * This test checks the API's contract enforcement for required fields of the
 * section creation endpoint. It iteratively omits each required field
 * ('channel_id', 'code', 'name', or 'enabled') in
 * IAiMallBackendSections.ICreate and attempts to create a section. For each
 * missing field case, this should result in a validation error response
 * specifying the missing property, confirming robust input validation.
 *
 * Steps:
 *
 * 1. Create a valid channel (channel must exist to test everything except missing
 *    'channel_id')
 * 2. For each required field in section creation: a. Attempt to create a section
 *    with that field explicitly set to undefined b. Verify that the API
 *    responds with a validation error mentioning the missing property
 * 3. (Sanity) Create a section with all required fields to demonstrate happy path
 */
export async function test_api_aiMallBackend_test_create_section_missing_required_fields(
  connection: api.IConnection,
) {
  // Step 1: Create a valid channel
  const tenantId = typia.random<string & tags.Format<"uuid">>();
  const channel = await api.functional.aiMallBackend.channels.create(
    connection,
    {
      body: {
        tenant_id: tenantId,
        code: `web_${RandomGenerator.alphaNumeric(4)}`,
        name: `Web Channel ${RandomGenerator.alphabets(5)}`,
        enabled: true,
      } satisfies IAiMallBackendChannels.ICreate,
    },
  );
  typia.assert(channel);

  // Step 2: Test missing required fields
  const validSection: IAiMallBackendSections.ICreate = {
    channel_id: channel.id,
    code: `main_${RandomGenerator.alphaNumeric(3)}`,
    name: `Main Section ${RandomGenerator.alphabets(4)}`,
    enabled: true,
  };

  const fields: (keyof IAiMallBackendSections.ICreate)[] = [
    "channel_id",
    "code",
    "name",
    "enabled",
  ];

  for (const field of fields) {
    // Create a shallow copy and set one required field to undefined (removes it from JSON in serialization)
    const sectionInput: any = { ...validSection };
    delete sectionInput[field];
    await TestValidator.error(`Missing required field: ${field}`)(async () => {
      await api.functional.aiMallBackend.sections.create(connection, {
        body: sectionInput,
      });
    });
  }

  // Step 3: Happy path - all fields present
  const section = await api.functional.aiMallBackend.sections.create(
    connection,
    {
      body: validSection,
    },
  );
  typia.assert(section);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IAiMallBackendChannels } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiMallBackendChannels";
import type { IAiMallBackendSections } from "@ORGANIZATION/PROJECT-api/lib/structures/IAiMallBackendSections";
import type { IPageIAiMallBackendSections } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIAiMallBackendSections";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test search and pagination of modular backend sections with combined filters.
 *
 * This E2E test verifies the aiMallBackend.sections.index endpoint can:
 *
 * - Correctly filter sections by channel, code, name, and enabled/disabled status
 * - Support paginated results with accurate navigation metadata
 *
 * Business context:
 *
 * - Multi-tenant channels are created, each with multiple modular sections for
 *   realistic coverage.
 * - Filtering covers channel, code, name, enabled status, and combined scenarios,
 *   ensuring precise match.
 * - Pagination accuracy is validated including meta: total count, page, limit,
 *   data quantity.
 *
 * Workflow:
 *
 * 1. Create two channels using unique tenants for isolation.
 * 2. For each channel, create three sections with distinct code, name, and enabled
 *    status.
 * 3. Search by channel_id to confirm channel isolation.
 * 4. Filter by channel_id + code + name + enabled for granular test.
 * 5. Check pagination with limit/page and verify correctness of navigation meta &
 *    result set.
 * 6. Fetch subsequent page and confirm expected number of results.
 * 7. Test enabled=false filter for one channel to verify negative filter and data
 *    separation.
 */
export async function test_api_aiMallBackend_test_search_sections_with_multiple_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create two unique channels (channel1 enabled, channel2 disabled)
  const tenantId1 = typia.random<string & tags.Format<"uuid">>();
  const tenantId2 = typia.random<string & tags.Format<"uuid">>();
  const channel1 = await api.functional.aiMallBackend.channels.create(
    connection,
    {
      body: {
        tenant_id: tenantId1,
        code: "web" + RandomGenerator.alphaNumeric(3),
        name: "Web Channel " + RandomGenerator.alphaNumeric(4),
        enabled: true,
      } satisfies IAiMallBackendChannels.ICreate,
    },
  );
  typia.assert(channel1);
  const channel2 = await api.functional.aiMallBackend.channels.create(
    connection,
    {
      body: {
        tenant_id: tenantId2,
        code: "mobile" + RandomGenerator.alphaNumeric(3),
        name: "Mobile Channel " + RandomGenerator.alphaNumeric(4),
        enabled: false,
      } satisfies IAiMallBackendChannels.ICreate,
    },
  );
  typia.assert(channel2);

  // 2. For each channel, create three sections with different config
  const sections: IAiMallBackendSections[] = [];
  for (const [channel, enabledList] of [
    [channel1, [true, false, true]],
    [channel2, [false, false, true]],
  ] as const) {
    for (let idx = 0; idx < 3; ++idx) {
      const section = await api.functional.aiMallBackend.sections.create(
        connection,
        {
          body: {
            channel_id: channel.id,
            code: `${channel.code}_section_${idx}`,
            name: `${channel.name} Section ${idx}`,
            enabled: enabledList[idx],
          } satisfies IAiMallBackendSections.ICreate,
        },
      );
      typia.assert(section);
      sections.push(section);
    }
  }

  // 3. Search by channel_id to confirm all and only that channel's sections
  const pagePerChannel = await api.functional.aiMallBackend.sections.index(
    connection,
    {
      body: {
        channel_id: channel1.id,
      } satisfies IAiMallBackendSections.IRequest,
    },
  );
  typia.assert(pagePerChannel);
  TestValidator.predicate("All results belong to channel1")(
    pagePerChannel.data.every((r) => r.channel_id === channel1.id),
  );
  TestValidator.equals("Correct result count for channel1")(
    pagePerChannel.data.length,
  )(3);
  TestValidator.equals("Pagination records")(pagePerChannel.pagination.records)(
    3,
  );

  // 4. Filter by channel_id, code, name, enabled: expect single match
  const section1of2 = sections.find(
    (s) => s.channel_id === channel2.id && s.code.endsWith("_section_1"),
  );
  TestValidator.predicate("section1of2 exists")(!!section1of2);
  const filtered = await api.functional.aiMallBackend.sections.index(
    connection,
    {
      body: {
        channel_id: channel2.id,
        code: section1of2!.code,
        name: section1of2!.name,
        enabled: section1of2!.enabled,
      } satisfies IAiMallBackendSections.IRequest,
    },
  );
  typia.assert(filtered);
  TestValidator.equals("Only one match for fully filtered search")(
    filtered.data.length,
  )(1);
  TestValidator.equals("Filtered code matches")(filtered.data[0].code)(
    section1of2!.code,
  );
  TestValidator.equals("Filtered name matches")(filtered.data[0].name)(
    section1of2!.name,
  );
  TestValidator.equals("Filtered enabled state matches")(
    filtered.data[0].enabled,
  )(section1of2!.enabled);
  TestValidator.equals("Filtered channel")(filtered.data[0].channel_id)(
    channel2.id,
  );

  // 5. Search channel1 with pagination limit=2, page=1
  const pagedFirst = await api.functional.aiMallBackend.sections.index(
    connection,
    {
      body: {
        channel_id: channel1.id,
        page: 1,
        limit: 2,
      } satisfies IAiMallBackendSections.IRequest,
    },
  );
  typia.assert(pagedFirst);
  TestValidator.equals("Page 1")(pagedFirst.pagination.current)(1);
  TestValidator.equals("Page size")(pagedFirst.pagination.limit)(2);
  TestValidator.equals("Pagination total")(pagedFirst.pagination.records)(3);
  TestValidator.equals("Pagination pages")(pagedFirst.pagination.pages)(2);
  TestValidator.equals("Data count on page 1")(pagedFirst.data.length)(2);
  TestValidator.predicate("All on channel1")(
    pagedFirst.data.every((r) => r.channel_id === channel1.id),
  );

  // 6. Fetch page 2 for channel1, should be 1 left
  const pagedSecond = await api.functional.aiMallBackend.sections.index(
    connection,
    {
      body: {
        channel_id: channel1.id,
        page: 2,
        limit: 2,
      } satisfies IAiMallBackendSections.IRequest,
    },
  );
  typia.assert(pagedSecond);
  TestValidator.equals("Page 2")(pagedSecond.pagination.current)(2);
  TestValidator.equals("Page size")(pagedSecond.pagination.limit)(2);
  TestValidator.equals("Data count on page 2")(pagedSecond.data.length)(1);
  TestValidator.equals("Pagination total")(pagedSecond.pagination.records)(3);
  TestValidator.predicate("All on channel1")(
    pagedSecond.data.every((r) => r.channel_id === channel1.id),
  );

  // 7. Enabled=false sections for channel2 only
  const channel2disabled = await api.functional.aiMallBackend.sections.index(
    connection,
    {
      body: {
